package school.magiccodex.paper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BagSyncSessionTest {
    private final UUID owner=UUID.randomUUID(), head=UUID.randomUUID(), snapshot=UUID.randomUUID();
    private BagSnapshotBinding binding(){return new BagSnapshotBinding(owner,snapshot,head,10,2,BagSnapshotBinding.hash("page2+hotbar+armor"));}
    private BagSyncSession ready(){var s=new BagSyncSession(owner);s.verifiedIncoming(binding(),head,10,2);s.complete(binding(),"page2+hotbar+armor");return s;}
    @Test void synchronizationCompleteMustMatchSnapshotInventoryAndCentralHead(){var s=new BagSyncSession(owner);assertThrows(IllegalStateException.class,()->s.beginSwitch(false));assertThrows(IllegalStateException.class,()->s.verifiedIncoming(binding(),UUID.randomUUID(),10,2));s.verifiedIncoming(binding(),head,10,2);assertThrows(IllegalStateException.class,()->s.complete(binding(),"page1"));assertEquals(BagSyncSession.Phase.VERIFYING,s.phase());}
    @Test void snapshotCaptureDuringSwitchCannotCombineOldInventoryAndNewPage(){var s=ready();s.beginSwitch(false);assertThrows(IllegalStateException.class,()->s.capture(UUID.randomUUID(),"old","old"));}
    @Test void nativeInventoryCapturedBeforeTheSwitchIsRejected(){var s=ready();assertThrows(IllegalStateException.class,()->s.capture(UUID.randomUUID(),"old","new"));}
    @Test void transferSealsInputAndRequiresBothNativeStoresToMatch(){var s=ready();s.seal();assertThrows(IllegalStateException.class,()->s.beginSwitch(false));var b=s.capture(UUID.randomUUID(),"items","items");assertThrows(IllegalStateException.class,()->s.nativeCommitVerified(b,b.snapshot(),"items",UUID.randomUUID(),"items"));assertThrows(IllegalStateException.class,()->s.nativeCommitVerified(b,b.snapshot(),"items",b.snapshot(),"old"));assertTrue(s.nativeCommitVerified(b,b.snapshot(),"items",b.snapshot(),"items"));}
    @Test void oldSaveCallbackCannotReleaseOwnershipAfterANewerCapture(){var s=ready();s.seal();var old=s.capture(UUID.randomUUID(),"old","old");s.finishCapture(true);var newer=s.capture(UUID.randomUUID(),"new","new");assertFalse(s.nativeCommitVerified(old,old.snapshot(),"old",old.snapshot(),"old"));assertTrue(s.nativeCommitVerified(newer,newer.snapshot(),"new",newer.snapshot(),"new"));}
    @Test void backgroundSaveDoesNotReleaseAnActiveSession(){var s=ready();var b=s.capture(UUID.randomUUID(),"items","items");assertFalse(s.nativeCommitVerified(b,b.snapshot(),"items",b.snapshot(),"items"));}
    @Test void disconnectOrCrashDuringSwitchFailsClosedAndCannotExportPartialState(){var s=ready();s.beginSwitch(false);s.seal();assertEquals(BagSyncSession.Phase.BLOCKED,s.phase());assertThrows(IllegalStateException.class,()->s.capture(UUID.randomUUID(),"items","items"));}
    @Test void onlyExactSwitchTokenCanCommitAndHuskLockBlocksInput(){var s=ready();assertThrows(IllegalStateException.class,()->s.beginSwitch(true));var op=s.beginSwitch(false);assertThrows(IllegalStateException.class,()->s.committedSwitch(UUID.randomUUID(),UUID.randomUUID(),11,1));s.committedSwitch(op,UUID.randomUUID(),11,1);assertEquals(BagSyncSession.Phase.READY,s.phase());assertThrows(IllegalStateException.class,()->s.committedSwitch(op,UUID.randomUUID(),12,2));}
    @Test void aCaptureBlocksBothAnotherCaptureAndPageSwitchUntilProofCompletes(){var s=ready();var b=s.capture(UUID.randomUUID(),"inv","inv");assertThrows(IllegalStateException.class,()->s.capture(UUID.randomUUID(),"inv","inv"));assertThrows(IllegalStateException.class,()->s.beginSwitch(false));s.finishCapture(true);assertEquals(BagSyncSession.Phase.READY,s.phase());}
    @Test void cleanEnrollmentStillWaitsForTheExactAppliedSnapshot(){var s=new BagSyncSession(owner);s.initializeClean(head);var b=s.capture(snapshot,"empty inventory","empty inventory");s.finishCapture(true);s.awaitLocalApply(b);assertThrows(IllegalStateException.class,()->s.beginSwitch(false));s.complete(b,"empty inventory");assertEquals(BagSyncSession.Phase.READY,s.phase());assertThrows(IllegalStateException.class,()->s.initializeClean(UUID.randomUUID()));}
    @Test void reconnectCannotBecomeReadyFromAnUnrelatedSnapshot(){var s=new BagSyncSession(owner);s.verifiedIncoming(binding(),head,10,2);var other=new BagSnapshotBinding(owner,UUID.randomUUID(),head,10,2,binding().inventoryHash());assertThrows(IllegalStateException.class,()->s.complete(other,"page2+hotbar+armor"));}
}
